solutions.naive:
class Solution:
    def lastStoneWeightII(self, stones: list[int]) -> int:
        best = sum(stones)
        def dfs(i: int, left: int, right: int) -> None:
            nonlocal best
            if i == len(stones):
                best = min(best, abs(left - right))
                return
            dfs(i + 1, left + stones[i], right)
            dfs(i + 1, left, right + stones[i])
        dfs(0, 0, 0)
        return best

solutions.better:
class Solution:
    def lastStoneWeightII(self, stones: list[int]) -> int:
        total = sum(stones)
        reachable = {0}
        for w in stones:
            reachable |= {s + w for s in reachable}
        return min(abs(total - 2 * s) for s in reachable)

solutions.optimal:
class Solution:
    def lastStoneWeightII(self, stones: list[int]) -> int:
        total = sum(stones)
        half = total // 2
        dp = [False] * (half + 1)
        dp[0] = True
        for w in stones:
            for s in range(half, w - 1, -1):
                dp[s] = dp[s] or dp[s - w]
        for s in range(half, -1, -1):
            if dp[s]:
                return total - 2 * s
        return total

